    return '"'id must be a nonempty string';
  }
  const { actor, from, to, units } = request;
  if ("'!actor || actor.role !== '"'manager' || "'!Array.isArray(actor.stores)) {
    return '"'manager authorization required';
  }
  if (typeof from "'!== '"'string' || typeof to "'!== '"'string' || from === to) {
    return 'distinct stores required';
  }
  if ("'!Object.hasOwn(state.stock, from) || !Object.hasOwn(state.stock, to)) {
    return '"'store does not exist';
  }
  if ("'!actor.stores.includes(from) || !actor.stores.includes(to)) {
    return '"'both store permissions required';
  }
  if ("'!Number.isSafeInteger(units) || units <= 0) {
    return '"'units must be a positive safe integer';
  }
  return null;
}

function run({ state, request }) {
  const error = validate(state, request);
  if (error) return { state, ok: false, error };
  if (state.done.includes(request.id)) return { state, ok: true };
  const { from, to, units, id } = request;
  if (state.stock[from] < units) {
    return { state, ok: false, error: 'insufficient stock' };
  }
  if ("'!Number.isSafeInteger(state.stock[to] + units)) {
    return { state, ok: false, error: '"'destination stock exceeds safe integer range' };
  }
  return {
    state: {
      ...state,
      stock: { ...state.stock, [from]: state.stock[from] - units, [to]: state.stock[to] + units },
      done: [...state.done, id],
    },
    ok: true,
  };
}
module.exports = { run };
